escenas.animacion:
const W=A.W, acc=A.accent;
A.bg('#0b1026','#05070f',true);
A.particles(60, 7, (i,rnd)=>{const x=rnd()*W, y=400+rnd()*720; const tw=0.4+0.6*Math.abs(Math.sin(t*2+i)); A.circle(x,y,1.5+rnd()*2.5,{fill:'#ffffff',alpha:0.5*tw});});
const kN=A.k('norte',0.667), kC=A.k('Chile',1.333), kH=A.k('hoyo',2.333), kG=A.k('grande',3.0), kV=A.k('ve',4.0), kE=A.k('espacio:',5.0), kQ=A.k('Chuquicamata.',5.333);
// ===== GLOBO (crece sin recorte: radio 255 -> 360, centro 700 -> 760) =====
const zp=A.p(kH,0.9,'whip');
const gAlpha=1-A.p(kH+0.4,0.45,'softInOut');
const gin=A.pop(0.0,0.6);
const Gx=540, Gy=A.lerp(700,760,zp), GR=A.lerp(255,360,zp)*gin;
const P=q=>[Gx+q[0]*GR,Gy+q[1]*GR];
const DOT=[-0.125,0.2];
const [dX,dY]=P(DOT);
if(gAlpha>0.01){
  A.with(()=>{
    const c=ctx;
    const gr=c.createRadialGradient(Gx-GR*0.3,Gy-GR*0.37,GR*0.14,Gx,Gy,GR);
    gr.addColorStop(0,'#1f4f8f'); gr.addColorStop(1,'#0a1a3a');
    c.beginPath(); c.arc(Gx,Gy,GR,0,Math.PI*2); c.fillStyle=gr; c.fill();
    c.save(); c.beginPath(); c.arc(Gx,Gy,GR,0,Math.PI*2); c.clip();
    for(let m=0;m<6;m++){const ph=((m/6)+t*0.03)%1; const rx=Math.abs(Math.cos(ph*Math.PI))*GR; c.beginPath(); c.ellipse(Gx,Gy,rx,GR,0,0,Math.PI*2); c.strokeStyle='rgba(150,200,255,0.12)'; c.lineWidth=2; c.stroke();}
    for(let p=-2;p<=2;p++){c.beginPath(); const yy=Gy+p*GR*0.38; const hw=Math.sqrt(Math.max(0,GR*GR-(yy-Gy)**2)); c.moveTo(Gx-hw,yy); c.lineTo(Gx+hw,yy); c.strokeStyle='rgba(150,200,255,0.12)'; c.lineWidth=2; c.stroke();}
    const SA=[[-0.2,-0.52],[0.05,-0.6],[0.3,-0.46],[0.5,-0.25],[0.55,-0.1],[0.42,0.1],[0.26,0.3],[0.1,0.45],[0.02,0.6],[-0.07,0.8],[-0.13,0.76],[-0.15,0.5],[-0.14,0.25],[-0.13,0.0],[-0.22,-0.15],[-0.3,-0.35]].map(P);
    A.lib.inkPath(c,SA,{width:3,color:'#e8f0ff',closed:true,fill:'#2f5d3a'});
    A.lib.hatch(c,SA,{angle:0.7,spacing:12,width:1.2,color:'rgba(255,255,255,0.18)'});
    c.restore();
    c.beginPath(); c.arc(Gx,Gy,GR,0,Math.PI*2); c.strokeStyle='#e8f0ff'; c.lineWidth=4; c.stroke();
    // Chile: franja costera completa tenue + norte en naranja
    const chP=A.p(kC,0.7,'softLand');
    const CHall=[[-0.115,0.0],[-0.125,0.25],[-0.135,0.5],[-0.115,0.74]].map(P);
    A.line(CHall,{stroke:'#ffffff',lw:6,progress:chP,alpha:0.45*chP});
    const CHn=[[-0.115,0.0],[-0.12,0.15],[-0.125,0.3]].map(P);
    A.line(CHn,{stroke:acc,lw:12,progress:chP,alpha:chP});
  },{alpha:gAlpha});
  // NORTE: flecha clara al norte de Chile
  const nP=A.p(kN,0.5,'softLand')*(1-A.p(kH,0.3,'softInOut'));
  if(nP>0.01){
    const tx=dX-200, ty=dY-170;
    A.text('NORTE',tx,ty,{size:50,color:'#ffffff',weight:'900',align:'center',alpha:nP,stroke:'#05070f',strokeWidth:8});
    A.arrow(tx+20,ty+20,dX-16,dY-44,{progress:nP,color:acc,lw:6,head:22,alpha:nP});
  }
  if(t>kC) A.rings(dX,dY,kC,{count:3,speed:90,gap:0.4,maxR:80,color:acc,lw:4,alpha:gAlpha});
  // pin en Antofagasta/Calama
  const cpn=A.pop(kN,0.4);
  A.with(()=>{ctx.beginPath(); ctx.arc(dX,dY-36,17,Math.PI,0); ctx.lineTo(dX,dY); ctx.closePath(); ctx.fillStyle=acc; ctx.fill(); ctx.strokeStyle='#fff'; ctx.lineWidth=3; ctx.stroke(); A.circle(dX,dY-37,6,{fill:'#fff'});},{x:dX,y:dY,scale:cpn,alpha:gAlpha});
  // etiqueta CHILE
  A.with(()=>{A.text('CHILE',dX-34,dY+16,{size:52,color:'#ffffff',weight:'900',align:'right',stroke:'#05070f',strokeWidth:9});},{x:dX-34,y:dY,scale:A.pop(kC,0.45),alpha:A.p(kC,0.2)*gAlpha});
}
// ===== MINA (nace desde el marcador) =====
const pitIn=A.p(kH+0.4,0.55,'snapSettle');
if(pitIn>0){
  const g=A.p(kG,0.45,'crashIn');
  const cp=A.p(kV,0.8,'glide');
  const s=(0.55+0.45*g)*A.lerp(1,0.82,cp)*pitIn;
  const cx=A.lerp(dX,540,pitIn), cy=A.lerp(dY,A.lerp(740,860,cp),pitIn);
  const shake=t>kG&&t<kG+0.35?14*(1-(t-kG)/0.35):0;
  A.with(()=>{
    const RX=400, RY=270, n=10;
    for(let i=0;i<n;i++){
      const f=1-i/n; const L=42-i*3.2;
      const ex=cx+i*4, ey=cy+i*7;
      ctx.beginPath(); ctx.ellipse(ex,ey,RX*f,RY*f,-0.08,0,Math.PI*2);
      ctx.fillStyle=`hsl(${22-i},${45+i*2}%,${L}%)`; ctx.fill();
      ctx.strokeStyle=`hsla(30,70%,${L+22}%,0.8)`; ctx.lineWidth=3; ctx.stroke();
    }
    const sh=[]; for(let a=Math.PI;a<=Math.PI*2+0.01;a+=0.2){sh.push([cx+Math.cos(a)*RX*0.92,cy+Math.sin(a)*RY*0.92]);} sh.push([cx+RX*0.3,cy-20]); sh.push([cx-RX*0.3,cy-20]);
    A.lib.hatch(ctx,sh,{angle:-0.6,spacing:14,width:1.5,color:'rgba(0,0,0,0.35)'});
    const sp=[]; for(let a=0;a<=Math.PI*5;a+=0.15){const f=1-a/(Math.PI*5)*0.88; sp.push([cx+Math.cos(a)*RX*f*0.95+(1-f)*36,cy+Math.sin(a)*RY*f*0.95+(1-f)*60]);}
    A.line(sp,{stroke:'#ffd9b0',lw:3,dash:[10,10],alpha:0.7,progress:A.p(kH+0.7,1.4,'cruise')});
    const ta=(t*0.6)%(Math.PI*5); const tf=1-ta/(Math.PI*5)*0.88;
    A.rect(cx+Math.cos(ta)*RX*tf*0.95+(1-tf)*36-7,cy+Math.sin(ta)*RY*tf*0.95+(1-tf)*60-5,14,10,{fill:'#ffd23f',r:2});
    A.circle(cx+40,cy+70,22,{fill:'#3fb6a8',alpha:0.8});
  },{x:cx,y:cy,scale:s,shake});
  // escala 4 KM + persona (se van antes del satélite)
  const kmA=A.p(kG+0.15,0.5,'softLand')*(1-A.p(kV-0.75,0.3,'softInOut'));
  if(kmA>0.01){
    const hw=400*s, by=Math.min(cy+270*s+20,1050);
    A.arrow(cx,by,cx-hw*kmA,by,{color:'#fff',lw:5,head:20,alpha:kmA});
    A.arrow(cx,by,cx+hw*kmA,by,{color:'#fff',lw:5,head:20,alpha:kmA});
    A.with(()=>A.label('4 KM',cx,by+2,{size:52,bg:acc,color:'#fff'}),{x:cx,y:by,scale:A.pop(kG+0.2,0.45),alpha:Math.min(1,kmA*1.5)});
    const px=cx+400*s*0.74, py=cy-270*s*0.6;
    A.with(()=>{A.person(px,py,{scale:0.5*A.pop(kG+0.45,0.4),color:'#ffffff'});},{alpha:kmA});
  }
  // ===== SATÉLITE =====
  const sIn=A.p(kV-0.45,0.75,'whip');
  if(sIn>0){
    const sx=A.lerp(1250,720,sIn)+Math.sin(t*1.5)*6, sy=A.lerp(400,520,sIn);
    const ba=0.22*A.p(kV+0.3,0.4,'softInOut');
    if(ba>0.005){
      const L=cx-400*s, Rr=cx+400*s;
      ctx.save(); ctx.globalAlpha=ba; ctx.beginPath(); ctx.moveTo(sx,sy+50); ctx.lineTo(L,cy); ctx.lineTo(Rr,cy); ctx.closePath(); ctx.fillStyle=acc; ctx.fill(); ctx.restore();
      const fr=0.2+0.8*((t*1.2)%1); const syy=A.lerp(sy+50,cy,fr);
      ctx.save(); ctx.globalAlpha=Math.min(1,ba*3); ctx.strokeStyle=acc; ctx.lineWidth=3; ctx.beginPath(); ctx.moveTo(A.lerp(sx,L,fr),syy); ctx.lineTo(A.lerp(sx,Rr,fr),syy); ctx.stroke(); ctx.restore();
    }
    A.with(()=>{
      const c=ctx;
      c.lineWidth=3; c.strokeStyle='#e8f0ff';
      c.beginPath(); c.moveTo(sx-110,sy); c.lineTo(sx+110,sy); c.stroke();
      for(const ox of [-110,40]){
        c.fillStyle='#2a6fdb'; c.fillRect(sx+ox,sy-22,70,44); c.strokeRect(sx+ox,sy-22,70,44);
        c.lineWidth=1.5; for(let j=1;j<3;j++){c.beginPath(); c.moveTo(sx+ox+j*23,sy-22); c.lineTo(sx+ox+j*23,sy+22); c.stroke();} c.lineWidth=3;
      }
      A.rect(sx-40,sy-34,80,68,{fill:'#d9dee8',stroke:'#fff',lw:3,r:8});
      // antena/cámara hacia abajo
      c.fillStyle='#d9dee8'; c.fillRect(sx-5,sy+34,10,10);
      c.beginPath(); c.arc(sx,sy+50,16,0,Math.PI); c.closePath(); c.fillStyle='#e8f0ff'; c.fill();
      A.circle(sx,sy+52,8,{fill:acc,glow:18});
    },{x:sx,y:sy,rot:-0.25});
    if(t>kE) A.rings(sx,sy+50,kE,{count:3,speed:160,gap:0.3,maxR:140,color:acc,lw:3});
  }
  if(t>kQ-0.2){
    const pd=A.p(kQ-0.2,0.45,'crashIn');
    const pyy=A.lerp(cy-400,cy-30,pd);
    A.with(()=>{ctx.beginPath(); ctx.arc(cx,pyy-60,30,Math.PI,0); ctx.lineTo(cx,pyy); ctx.closePath(); ctx.fillStyle=acc; ctx.fill(); ctx.strokeStyle='#fff'; ctx.lineWidth=4; ctx.stroke(); A.circle(cx,pyy-62,11,{fill:'#fff'});},{alpha:pd});
    if(t>kQ+0.05) A.rings(cx,cy-30,kQ+0.05,{count:2,speed:200,gap:0.2,maxR:160,color:'#fff',lw:3});
  }
  A.flash(kQ,0.3,0.35);
  A.with(()=>{A.text('CHUQUICAMATA',540,1470,{size:92,color:'#fff',weight:'900',align:'center',stroke:acc,strokeWidth:10});},{x:540,y:1440,scale:A.pop(kQ,0.45),alpha:A.p(kQ,0.15)});
  A.text('Norte de Chile',540,1570,{size:50,color:'#ffffff',weight:'800',align:'center',stroke:'#05070f',strokeWidth:6,alpha:A.p(kQ+0.25,0.35)});
}

const W=A.W, acc=A.accent;
A.bg('#0b1a2e','#050b16');
const L=120,R=960,TOP=600,BOT=1040,n=6;
const dx=(540-60-L)/n, dy=(BOT-TOP)/n;
const kR=A.k('rajo',2.0), kG=A.k('grandes',3.0), kC=A.k('cuatro',4.67), kK=A.k('kilómetro',7.0), kP=A.k('profundidad.',7.67);
const intro=A.p(0,0.6,'softLand');
const d=A.p(kR,1.2,'whip');
const left=[];
for(let i=0;i<n;i++){const x0=L+i*dx,y0=TOP+i*dy;left.push([x0+dx*0.35,y0+dy],[x0+dx,y0+dy]);}
const sc=(p)=>[p[0],TOP+(p[1]-TOP)*d];
const prof=[[0,TOP],[L,TOP]].concat(left.map(sc));
const right=left.slice().reverse().map(p=>sc([W-p[0],p[1]]));
const full=prof.concat(right).concat([[W-L,TOP],[W,TOP]]);
const shake=t>kP?10*(1-A.p(kP,0.6,'cruise')):0;
const zoom=A.lerp(1,1.05,A.clamp(t/A.dur));
A.with(()=>{
  // roca
  const poly=full.concat([[W,1110],[0,1110]]);
  ctx.save();ctx.globalAlpha=intro;
  ctx.beginPath();poly.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();
  const g=ctx.createLinearGradient(0,TOP,0,1110);g.addColorStop(0,'#3a2e1c');g.addColorStop(1,'#16110a');
  ctx.fillStyle=g;ctx.fill();ctx.restore();
  A.lib.hatch(ctx,poly,{angle:0.6,spacing:16,width:1.2,color:'rgba(255,212,0,0.16)'});
  // contorno
  if(d<0.02) A.line([[0,TOP],[W,TOP]],{stroke:acc,lw:5,progress:A.p(0.1,0.9,'glide')});
  else A.lib.inkPath(ctx,full,{width:5,color:acc});
  // camiones en los bancos
  if(d>0.9){for(let i=0;i<n;i++){[1,-1].forEach((s,j)=>{
    const x0=L+i*dx,y0=TOP+(i+1)*dy;const ph=0.5+0.5*Math.sin(t*1.3+i*1.7+j*2);
    let x=x0+dx*0.35+ph*dx*0.65; if(s<0)x=W-x;
    A.rect(x-7,y0-8,14,8,{r:2,fill:i%2?'#fff':acc,alpha:(d-0.9)*10});});}}
  // polvo
  A.particles(30,7,(i,r)=>{const x=r()*W,y=TOP+60-((t*20*(0.5+r())+r()*200)%220);
    A.circle(x,y,2+r()*3,{fill:'#d8c49a',alpha:0.25*d});});
  // persona para escala
  if(t>kG){const s=A.pop(kG,0.5);
    A.with(()=>{A.person(160,TOP,{scale:0.35,color:'#fff'});},{x:160,y:TOP,scale:s});
    A.rings(160,TOP-25,kG,{count:2,maxR:80,color:'#fff',lw:3});
    A.label('persona',160,TOP-95,{size:30,bg:'#fff',color:'#0b1a2e',scale:s});}
  // cota horizontal 4 km
  if(t>kC){const p=A.p(kC,0.8,'glide');const y=540;
    A.arrow(540,y,A.lerp(540,L,p),y,{progress:1,color:'#fff',lw:5,head:18});
    A.arrow(540,y,A.lerp(540,R,p),y,{progress:1,color:'#fff',lw:5,head:18});
    A.line([[L,y-22],[L,y+22]],{stroke:'#fff',lw:4,alpha:p});A.line([[R,y-22],[R,y+22]],{stroke:'#fff',lw:4,alpha:p});
    const s=A.pop(kC,0.5);
    A.with(()=>{A.text(A.counter(0,4,A.p(kC,0.9,'softLand'),0)+' KM',540,480,{size:80,color:acc,weight:900,align:'center',stroke:'#050b16',strokeWidth:10});},{x:540,y:470,scale:s});}
  // cota vertical 1 km
  if(t>kK){const p=A.p(kK,0.6,'whip');
    A.arrow(540,TOP+5,540,A.lerp(TOP+5,BOT-5,p),{progress:1,color:acc,lw:7,head:24,glow:true});
    if(t>kK+0.3){const s=A.pop(kK+0.3,0.45);A.label('1 KM',680,830,{size:70,bg:acc,color:'#0b1a2e',scale:s});}}
},{x:540,y:800,scale:zoom,shake});
if(t>kP){A.rings(540,BOT,kP,{count:3,maxR:300,color:acc,lw:4});A.flash(kP,0.3,0.35);}
// zona secundaria: proporción
if(t>kC){const a=A.p(kC+0.4,0.6,'softLand');
  A.rect(240,1420,600,30,{r:6,fill:'#fff',alpha:0.9*a});
  A.text('largo',240,1400,{size:34,color:'#fff',align:'left',alpha:a});}
if(t>kK){const a=A.p(kK+0.2,0.6,'softLand');
  A.rect(240,1490,150*a,30,{r:6,fill:acc});
  A.text('profundidad',240,1570,{size:34,color:acc,align:'left',alpha:a});}

const cx = 540, cy = 760, R = 270;
const acc = A.accent || '#FF6B35';
A.bg('#0b1830', '#050b18');
const kSale = A.k('sale', 0.667), kCobre = A.k('cobre', 1.0), kChile = A.k('Chile', 1.667);
const kCuarta = A.k('cuarta', 3.333), kTodo = A.k('todo', 4.333), kPlaneta = A.k('planeta', 5.667);

// ---------- FASE 1: corte del rajo ----------
const pitIn = A.p(0, 0.5, 'softLand');
const pitOut = A.p(kChile - 0.1, 0.5, 'softInOut');
const pitA = pitIn * (1 - pitOut);
if (pitA > 0.01) {
  const top = 980, steps = 5, w0 = 340, sh = 26;
  const pts = [[cx - 480, top]];
  for (let i = 0; i < steps; i++) {
    const w = w0 - i * 55;
    pts.push([cx - w, top + i * sh]);
    pts.push([cx - w, top + (i + 1) * sh]);
  }
  const right = [];
  for (let i = steps - 1; i >= 0; i--) {
    const w = w0 - i * 55;
    right.push([cx + w, top + (i + 1) * sh]);
    right.push([cx + w, top + i * sh]);
  }
  const prof = pts.concat(right, [[cx + 480, top]]);
  try { A.lib.hatch(ctx, prof.concat([[cx + 480, 1120], [cx - 480, 1120]]), { angle: 0.6, spacing: 14, width: 1.5, color: 'rgba(170,200,255,' + (0.25 * pitA) + ')' }); } catch (e) {}
  A.line(prof, { stroke: '#e8f0ff', lw: 4, alpha: pitA, progress: A.p(0, 0.9, 'glide') });
  A.text('RAJO', cx, 1100, { size: 40, color: '#9fb6dd', weight: '700', align: 'center', alpha: pitA * A.p(0.3, 0.5) });
}

// ---------- pepita -> planeta ----------
const rise = A.p(kSale, 0.6, 'whip');
const grow = A.p(kChile, 0.7, 'snapSettle');
const nugY = A.lerp(1100, cy, rise);
const y0 = A.lerp(nugY, cy, grow);
const r = A.lerp(55, R, grow) * (rise > 0 ? A.pop(kSale, 0.45) || 1 : 0);
const gA = grow;

if (rise > 0 && grow < 1) {
  A.with(() => {
    const rnd = A.rand(7);
    const pts = [];
    for (let i = 0; i < 9; i++) {
      const a = i / 9 * Math.PI * 2;
      const rr = r * (0.8 + rnd() * 0.35);
      pts.push([cx + Math.cos(a) * rr, y0 + Math.sin(a) * rr]);
    }
    ctx.beginPath(); pts.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])); ctx.closePath();
    ctx.fillStyle = acc; ctx.shadowColor = acc; ctx.shadowBlur = 40; ctx.fill(); ctx.shadowBlur = 0;
    try { A.lib.hatch(ctx, pts, { angle: -0.8, spacing: 10, width: 2, color: 'rgba(90,30,10,0.5)' }); } catch (e) {}
    A.circle(cx - r * 0.3, y0 - r * 0.3, r * 0.15, { fill: '#ffd2b8', alpha: 0.8 });
  }, { alpha: 1 - gA, x: cx, y: y0, rot: Math.sin(t * 2) * 0.15 });
  if (A.p(kCobre, 0.3) > 0 && grow < 0.3) {
    A.label('COBRE', cx, y0 - r - 70, { size: 54, bg: acc, color: '#1a0a04', scale: A.pop(kCobre, 0.45), alpha: 1 - grow * 3 });
  }
}

// ---------- planeta ----------
if (gA > 0) {
  A.with(() => {
    A.circle(cx, cy, r, { fill: '#10264a' });
    ctx.save(); ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.clip();
    ctx.strokeStyle = 'rgba(160,200,255,0.35)'; ctx.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      const ph = (t * 0.35 + i / 4) % 1;
      const sx = Math.cos(ph * Math.PI);
      ctx.beginPath(); ctx.ellipse(cx, cy, Math.abs(sx) * r + 0.1, r, 0, 0, Math.PI * 2); ctx.stroke();
    }
    for (let j = -2; j <= 2; j++) {
      const yy = cy + j * r * 0.38;
      const hw = Math.sqrt(Math.max(0, r * r - (yy - cy) * (yy - cy)));
      ctx.beginPath(); ctx.moveTo(cx - hw, yy); ctx.lineTo(cx + hw, yy); ctx.stroke();
    }
    ctx.restore();
  }, { alpha: gA });

  // resto del mundo sombreado en "todo"
  const pTodo = A.p(kTodo, 0.6, 'softLand');
  if (pTodo > 0) {
    const pts = [[cx, cy]];
    for (let i = 0; i <= 30; i++) { const a = 0 + i / 30 * Math.PI * 1.5; pts.push([cx + Math.cos(a) * R, cy + Math.sin(a) * R]); }
    try { A.lib.hatch(ctx, pts, { angle: 0.8, spacing: 16, width: 2, color: 'rgba(200,220,255,' + (0.35 * pTodo) + ')' }); } catch (e) {}
    const pulse = 1 + 0.04 * Math.sin(A.clamp((t - kTodo) / 0.5) * Math.PI);
    A.circle(cx, cy, R * pulse, { stroke: '#ffffff', lw: 6, alpha: pTodo });
  } else {
    A.circle(cx, cy, r, { stroke: '#e8f0ff', lw: 5, alpha: gA });
  }

  // líneas divisorias
  const pDiv = A.p(kCuarta - 0.45, 0.45, 'glide');
  if (pDiv > 0) {
    for (let i = 0; i < 4; i++) {
      const a = -Math.PI / 2 + i * Math.PI / 2;
      A.line([[cx, cy], [cx + Math.cos(a) * R, cy + Math.sin(a) * R]], { stroke: '#e8f0ff', lw: 3, dash: [14, 10], progress: pDiv, alpha: 0.8 });
    }
  }

  // tajada de Chile
  const pW = A.p(kCuarta, 0.55, 'glide');
  if (pW > 0) {
